async fn vault_messages_react(
    server: &Arc<SyncServer>,
    call: &FacadeCall<'_>,
    input: Result<serde_json::Value, FacadeApiError>,
) -> Result<FacadeCallOutput, FacadeApiError> {
    let auth = call.auth();
    auth.require(CoreScope::Write)?;
    auth.require_unrestricted_record_scope()?;
    facade_outside_room_turn(call, "vault.messages.react")?;
    let value = input?;
    oneiron::task_verb::sdk::validate_input("vault.messages.react", &value)?;
    let mut hooks = facade_hooks_pre(server, call, "vault.messages.react", value).await?;
    let ran = async {
        let (output, listed) =
            super::host_doors::vault_messages_react(server, auth, facade_door_input(&mut hooks)?)
                .await;
        Ok::<_, FacadeApiError>((facade_output(output?)?, listed))
    }
    .await;
    let (output, listed) = match ran {
        Ok(ran) => ran,
        Err(error) => {
            row_hooks_abort(server, hooks).await;
            return Err(error);
        }
    };
    Ok(FacadeCallOutput {
        value: facade_hooks_post(server, hooks, output).await?,
        rows: super::host_doors::ListedRows::rows(listed),
    })
}
